#nullable enable // autogenerated

using System;
using MVZ2.Managers;
using MVZ2Logic.Resources;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Localization
{
    public abstract class ResourcePackReaderV1 : ResourcePackReader
    {
        protected ResourcePackReaderV1(MainManager main) : base(main)
        {
        }
        protected Sprite CreateSprite(Texture2D texture2D, ResourcePackSprite packSprite, string generatedCategory, string generatedName)
        {
            try
            {
                Rect rect;
                if (packSprite.single)
                {
                    rect = new Rect(0, 0, texture2D.width, texture2D.height);
                }
                else
                {
                    rect = new Rect(packSprite.x, packSprite.y, packSprite.width, packSprite.height);
                }
                var pivot = new Vector2(packSprite.pivotX, packSprite.pivotY);
                rect.width = Math.Min(rect.width, texture2D.width);
                rect.height = Math.Min(rect.height, texture2D.height);
                var spr = Main.ResourceManager.CreateSprite(texture2D, rect, pivot, generatedName, generatedCategory);
                return spr;
            }
            catch (Exception e)
            {
                Debug.LogError($"An exception thrown when loading sprite {generatedName} from a language pack: {e}");
                return Main.ResourceManager.GetDefaultSpriteClone();
            }
        }
        public const string MANIFEST_FILENAME = "manifest.json";
    }
}
